import{_ as t,o as a,c as r,ah as n}from"./chunks/framework.C-FRNfAJ.js";const h=JSON.parse('{"title":"Paiements","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"guide/apprenant/paiements.md","filePath":"src/guide/apprenant/paiements.md"}'),s={name:"guide/apprenant/paiements.md"};function o(i,e,u,c,d,l){return a(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="paiements" tabindex="-1">Paiements <a class="header-anchor" href="#paiements" aria-label="Permalink to &quot;Paiements&quot;">​</a></h1><p>Le prix de la formation se règle en <strong>trois tranches</strong>, définies par votre convention. Vous suivez factures et échéances dans <strong>Parcours → Mon inscription</strong>, rubrique « Factures ».</p><h2 id="l-echeancier-30-40-30" tabindex="-1">L&#39;échéancier 30 / 40 / 30 <a class="header-anchor" href="#l-echeancier-30-40-30" aria-label="Permalink to &quot;L&#39;échéancier 30 / 40 / 30&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tranche</th><th>Part du prix</th><th>Date d&#39;échéance</th></tr></thead><tbody><tr><td>Signature</td><td>30 %</td><td>Au démarrage de la cohorte, ou à la signature si elle est postérieure</td></tr><tr><td>Mi-parcours</td><td>40 %</td><td>Au milieu de la cohorte</td></tr><tr><td>Solde</td><td>30 %</td><td>Avant la fin de la cohorte</td></tr></tbody></table><p>Les dates exactes figurent dans votre convention. Les montants sont <strong>hors taxe</strong> : la facture porte la mention d&#39;exonération et les modalités de paiement.</p><h2 id="les-factures" tabindex="-1">Les factures <a class="header-anchor" href="#les-factures" aria-label="Permalink to &quot;Les factures&quot;">​</a></h2><p>Chaque tranche donne une facture (référence <code>FAC-NB-AAAA-XXX</code>), envoyée en PDF par e-mail et disponible dans <strong>Mes documents</strong> :</p><ul><li>la première est émise à la <strong>contre-signature</strong> de votre convention ;</li><li>les deux suivantes sont émises <strong>15 jours avant</strong> leur échéance.</li></ul><p>Si une entreprise vous finance en partie, chaque tranche est facturée en <strong>deux factures distinctes</strong> : la vôtre pour votre part, la sienne pour la sienne. Chacune est suivie séparément.</p><h2 id="comment-payer" tabindex="-1">Comment payer <a class="header-anchor" href="#comment-payer" aria-label="Permalink to &quot;Comment payer&quot;">​</a></h2><p>Les paiements sont <strong>reçus hors de Kura</strong>, puis enregistrés par le Coordinateur pédagogique avec le montant, le moyen, la référence et la date. Vous pouvez régler par virement, chèque, Mobile Money (Flooz, T-Money), carte bancaire ou espèces. Les modalités précises de paiement figurent sur chaque facture.</p><p>Un paiement <strong>partiel</strong> est possible ; l&#39;enregistrement ne peut jamais dépasser le montant dû. À chaque paiement enregistré, vous recevez un accusé.</p><h2 id="les-rappels" tabindex="-1">Les rappels <a class="header-anchor" href="#les-rappels" aria-label="Permalink to &quot;Les rappels&quot;">​</a></h2><p>Kura vous prévient avant et après chaque échéance, par e-mail, et aussi dans Sève et sur WhatsApp si votre compte est ouvert et votre téléphone renseigné :</p><ul><li><strong>15, 7 et 1 jours avant</strong> l&#39;échéance ;</li><li><strong>le lendemain</strong> de l&#39;échéance, si la tranche n&#39;est pas réglée.</li></ul><h2 id="si-une-tranche-n-est-pas-payee" tabindex="-1">Si une tranche n&#39;est pas payée <a class="header-anchor" href="#si-une-tranche-n-est-pas-payee" aria-label="Permalink to &quot;Si une tranche n&#39;est pas payée&quot;">​</a></h2><p>La chronologie est la même pour toutes les tranches :</p><table tabindex="0"><thead><tr><th>Moment</th><th>Ce qui se passe</th></tr></thead><tbody><tr><td>Échéance</td><td>La tranche doit être réglée</td></tr><tr><td>J+1</td><td>Rappel automatique</td></tr><tr><td>J+7</td><td>Le Coordinateur vous contacte (e-mail ou appel)</td></tr><tr><td>J+15</td><td>La facture passe « En retard ». Un <strong>moratoire de 15 jours</strong> démarre, automatique et unique. Vous êtes prévenu</td></tr><tr><td>J+30</td><td>Sans paiement, votre <strong>accès à Sève est suspendu</strong>. Vous êtes prévenu</td></tr><tr><td>Après J+30</td><td>Entretien avec le Coordinateur, plan de régularisation éventuel ; désinscription si aucune régularisation</td></tr></tbody></table><p><strong>Payer, à n&#39;importe quel moment, rétablit votre accès automatiquement.</strong> La suspension ne concerne que Sève : vos documents et votre dossier Kura restent consultables.</p><p>Si c&#39;est le <strong>financeur</strong> qui est en retard, votre accès est suspendu aussi, même si votre propre part est réglée.</p><h2 id="si-votre-situation-change" tabindex="-1">Si votre situation change <a class="header-anchor" href="#si-votre-situation-change" aria-label="Permalink to &quot;Si votre situation change&quot;">​</a></h2><ul><li><strong>Report ou force majeure.</strong> Vous changez de cohorte : ce que vous avez payé est conservé. Le reste dû des factures déjà émises est annulé par un <strong>avoir</strong> (<code>AV-NB-AAAA-XXX</code>), et la nouvelle convention refacture chaque tranche en déduisant ce que vous avez déjà réglé.</li><li><strong>Cohorte annulée par NextBoxx</strong> avant son démarrage : Kura émet un avoir de <strong>remboursement de 100 %</strong> des sommes payées. Le Coordinateur enregistre le remboursement une fois effectué.</li><li><strong>Abandon.</strong> Aucun avoir : les tranches qui n&#39;ont pas encore été facturées ne le seront plus, mais les factures déjà émises restent dues. Vous recevez une attestation partielle sur les blocs validés (voir <a href="./certification.html#si-vous-abandonnez">Certificat et Canopé</a>).</li></ul><h2 id="le-solde-conditionne-le-certificat" tabindex="-1">Le solde conditionne le certificat <a class="header-anchor" href="#le-solde-conditionne-le-certificat" aria-label="Permalink to &quot;Le solde conditionne le certificat&quot;">​</a></h2><p>Le <strong>solde intégralement payé</strong> est l&#39;une des quatre conditions du certificat (voir <a href="./certification.html">Certificat et Canopé</a>).</p>',24)])])}const m=t(s,[["render",o]]);export{h as __pageData,m as default};
